import sympy

def solve():
    # The grid is 4x4.
    # Constraints:
    # 1. No two coins are orthogonally adjacent (Independent Set on Grid Graph).
    # 2. Every 2x2 subgrid must contain at least one coin.

    # The grid has 16 cells. We can represent the placement as a bitmask of 16 bits.
    # cell (r, c) is index r*4 + c.

    def is_valid_independent_set(mask):
        for r in range(4):
            for c in range(4):
                # Check right neighbor
                if c < 3:
                    if (mask & (1 << (r * 4 + c))) and (mask & (1 << (r * 4 + c + 1))):
                        return False
                # Check bottom neighbor
                if r < 3:
                    if (mask & (1 << (r * 4 + c))) and (mask & (1 << ((r + 1) * 4 + c))):
                        return False
        return True

    def satisfies_2x2_constraint(mask):
        # There are (4-1)*(4-1) = 9 2x2 squares
        for r in range(3):
            for c in range(3):
                # Check the 2x2 square starting at (r, c)
                has_coin = False
                for dr in range(2):
                    for dc in range(2):
                        if mask & (1 << ((r + dr) * 4 + (c + dc))):
                            has_coin = True
                            break
                    if has_coin: break
                if not has_coin:
                    return False
        return True

    count = 0
    # Iterate through all 2^16 possible placements
    for mask in range(1 << 16):
        if is_valid_independent_set(mask):
            if satisfies_2x2_constraint(mask):
                count += 1

    return count

if __name__ == "__main__":
    result = solve()
    print(f"ANSWER: {result}")
