def solve():
    # A 4x4 grid has 16 squares.
    # We can represent the placement of coins as a bitmask of length 16.
    # Indexing: (r, c) -> r * 4 + c

    # Constraints:
    # 1. No two coins are orthogonally adjacent.
    # 2. Each 2x2 square must have at least one coin.

    # Precompute orthogonal neighbors for each cell
    neighbors = []
    for r in range(4):
        for c in range(4):
            n = []
            if r > 0: n.append((r-1)*4 + c)
            if r < 3: n.append((r+1)*4 + c)
            if c > 0: n.append(r*4 + (c-1))
            if c < 3: n.append(r*4 + (c+1))
            neighbors.append(n)

    # Precompute 2x2 squares
    squares_2x2 = []
    for r in range(3):
        for c in range(3):
            sq = [
                r*4 + c, r*4 + c + 1,
                (r+1)*4 + c, (r+1)*4 + c + 1
            ]
            squares_2x2.append(sq)

    count = 0
    # There are 2^16 = 65536 possible placements.
    # Brute force search over all possible placements.
    for i in range(1 << 16):
        # Check orthogonal adjacency
        possible = True
        for cell in range(16):
            if (i >> cell) & 1:
                for neighbor in neighbors[cell]:
                    if (i >> neighbor) & 1:
                        possible = False
                        break
            if not possible:
                break

        if not possible:
            continue

        # Check 2x2 squares
        for sq in squares_2x2:
            has_coin = False
            for cell in sq:
                if (i >> cell) & 1:
                    has_coin = True
                    break
            if not has_coin:
                possible = False
                break

        if possible:
            count += 1

    return count

if __name__ == "__main__":
