import sympy

def solve():
    # Grid size
    N = 4
    # Possible states for a row (4 cells)
    # A state is a tuple of 0s and 1s.
    # Condition: No two coins are orthogonally adjacent (horizontally).
    valid_rows = []
    for i in range(1 << N):
        row = [(i >> j) & 1 for j in range(N)]
        # Check horizontal adjacency
        possible = True
        for j in range(N - 1):
            if row[j] == 1 and row[j+1] == 1:
                possible = False
                break
        if possible:
            valid_rows.append(tuple(row))

    # To handle the 2x2 condition, we need to track the previous row.
    # A 2x2 square consists of cells (r, c), (r, c+1), (r+1, c), (r+1, c+1).
    # The condition is: for all r in [0, N-2] and c in [0, N-2], 
    # at least one of these 4 cells must contain a coin.

    # dp[row_index][current_row_state] = number of ways
    # We start with row 0.
    dp = {}
    for row in valid_rows:
        dp[row] = 1

    for r in range(1, N):
        new_dp = {}
        for curr_row in valid_rows:
            count = 0
            for prev_row, ways in dp.items():
                # Check vertical adjacency
                vertical_ok = True
                for c in range(N):
                    if curr_row[c] == 1 and prev_row[c] == 1:
                        vertical_ok = False
                        break
                if not vertical_ok:
                    continue

                # Check 2x2 condition
                # For every c in 0..N-2, the 2x2 block at (r-1, c) must have a coin.
                two_by_two_ok = True
                for c in range(N - 1):
                    if (prev_row[c] == 0 and prev_row[c+1] == 0 and 
                        curr_row[c] == 0 and curr_row[c+1] == 0):
                        two_by_two_ok = False
                        break

                if two_by_two_ok:
                    count += ways
            if count > 0:
                new_dp[curr_row] = count
        dp = new_dp

    total_ways = sum(dp.values())
    return total_ways

if __name__ == "__main__":
    result = solve()
    print(f"ANSWER: {result}")
