import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def solve():
    # We need to find pairs (x, y) with x + y <= 20, x, y >= 1
    # such that there exists n >= 1 satisfying n = lcm(n, x) - gcd(n, y).
    # Let's rewrite the equation: lcm(n, x) - n = gcd(n, y).
    # Note that lcm(n, x) = nx / gcd(n, x).
    # So the equation is n * (x / gcd(n, x) - 1) = gcd(n, y).

    # Since x, y <= 20, and gcd(n, y) <= y <= 20, 
    # the value n * (x / gcd(n, x) - 1) must be small.
    # If x / gcd(n, x) - 1 > 0, then n must be small.
    # If x / gcd(n, x) - 1 = 0, then gcd(n, y) = 0, which is impossible for positive integers.
    # So x / gcd(n, x) must be at least 2.
    # Thus n * (2 - 1) <= gcd(n, y) <= y <= 20.
    # This means n <= 20.

    # We can brute force n from 1 up to a reasonable limit.
    # Since n <= y <= 20, checking n up to 20 is sufficient.

    valid_pairs = set()
    for x in range(1, 21):
        for y in range(1, 21):
            if x + y <= 20:
                # Check if there exists n >= 1 such that n = lcm(n, x) - gcd(n, y)
                # Based on the logic above, n must be <= 20.
                found = False
                for n in range(1, 21):
                    if n == lcm(n, x) - gcd(n, y):
                        found = True
                        break
                if found:
                    valid_pairs.add((x, y))

    return len(valid_pairs)

if __name__ == "__main__":
    result = solve()
    print(f"ANSWER: {result}")

